namespace DonationHub.Domain.Common;

public enum ErrorType
{
    Validation, Unauthorized, Forbidden, NotFound, Conflict,
    PayloadTooLarge, UnprocessableEntity, TooManyRequests, Failure
}

public record Error(string Code, string Message, ErrorType Type)
{
    public static readonly Error None = new(string.Empty, string.Empty, ErrorType.Failure);
}
// + ValidationError (أخطاء الحقول) و IResultFactory<TSelf> كما في Sprint 2

public class Result : IResultFactory<Result>
{
    // الـ constructor المحمي وفحوصه كما في Sprint 2
    public bool IsSuccess { get; }
    public bool IsFailure => !IsSuccess;
    public Error Error { get; }                      // Error.None عند النجاح

    public static Result Success() => new(true, Error.None);
    public static Result Failure(Error error) => new(false, error);
    public static implicit operator Result(Error error) => Failure(error);
}

public sealed class Result<TValue> : Result, IResultFactory<Result<TValue>>
{
    // الـ constructor الخاص والحقل _value كما في Sprint 2
    public TValue Value => IsSuccess ? _value! : throw new InvalidOperationException("Cannot access the value of a failed result.");

    public static Result<TValue> Success(TValue value) => new(value, true, Error.None);
    public static new Result<TValue> Failure(Error error) => new(default, false, error);
    public static implicit operator Result<TValue>(TValue value) => Success(value);
    public static implicit operator Result<TValue>(Error error) => Failure(error);
}

