using System.Security.Claims;
using DonationHub.Application.Common;            // Roles
using DonationHub.Domain.Campaigns;
using Microsoft.AspNetCore.Authorization;

namespace DonationHub.Api.Authorization;

public static class Policies
{
    public const string CampaignManagement = "CampaignManagement"; // دور: Admin أو CampaignManager
    public const string CampaignOwner = "CampaignOwner";           // مورد: Admin أو مالك الحملة
}

public sealed class CampaignOwnershipRequirement : IAuthorizationRequirement { }

public sealed class CampaignOwnershipHandler
    : AuthorizationHandler<CampaignOwnershipRequirement, Campaign>
{
    protected override Task HandleRequirementAsync(
        AuthorizationHandlerContext context,
        CampaignOwnershipRequirement requirement,
        Campaign resource)
    {
        if (context.User.IsInRole(Roles.Admin))
        {
            context.Succeed(requirement);          // الـ Admin يدير كل الحملات
            return Task.CompletedTask;
        }

        var isOwner = context.User.IsInRole(Roles.CampaignManager)
            && Guid.TryParse(context.User.FindFirstValue(ClaimTypes.NameIdentifier), out var userId)
            && resource.CreatedByUserId == userId;

        if (isOwner)
            context.Succeed(requirement);

        // لا نستدعي context.Fail(): عدم النجاح يكفي، ويسمح لـ handlers أخرى بالنجاح لو أُضيفت لاحقًا
        return Task.CompletedTask;
    }
}

