namespace DonationHub.Api.Authorization;

internal sealed class CurrentUser(IHttpContextAccessor accessor) : ICurrentUser
{
    private ClaimsPrincipal? User => accessor.HttpContext?.User;

    public bool IsAuthenticated => User?.Identity?.IsAuthenticated == true;

    public Guid UserId => IsAuthenticated
        ? User!.GetUserId()
        : throw new InvalidOperationException("There is no authenticated user.");

    public bool IsInRole(string role) => User?.IsInRole(role) == true;
}

internal sealed class CampaignAuthorizer(
    IAuthorizationService authorizationService,
    IHttpContextAccessor accessor) : ICampaignAuthorizer
{
    public async Task<bool> CanManageAsync(Campaign campaign)
    {
        var user = accessor.HttpContext?.User;
        if (user is null) return false;

        var result = await authorizationService.AuthorizeAsync(user, campaign, Policies.CampaignOwner);
        return result.Succeeded;
    }
}

using DonationHub.Api.Authorization;
using DonationHub.Application.Abstractions;
using DonationHub.Application.Common;            // Roles
using Microsoft.AspNetCore.Authorization;

namespace DonationHub.Api.Extensions;

public static class AuthorizationExtensions
{
    public static IServiceCollection AddApiAuthorization(this IServiceCollection services)
    {
        services.AddAuthorizationBuilder()
            .AddPolicy(Policies.CampaignManagement, policy =>
                policy.RequireRole(Roles.Admin, Roles.CampaignManager))
            .AddPolicy(Policies.CampaignOwner, policy =>
                policy.RequireAuthenticatedUser()
                      .AddRequirements(new CampaignOwnershipRequirement()));

        services.AddSingleton<IAuthorizationHandler, CampaignOwnershipHandler>(); // بلا حالة ← Singleton
        services.AddHttpContextAccessor();
        services.AddScoped<ICurrentUser, CurrentUser>();
        services.AddScoped<ICampaignAuthorizer, CampaignAuthorizer>();
        return services;
    }
}

