// نفس عقد Sprint 2 (يُرجع CampaignAdminResponse مع RowVersion الجديد)؛ الجديد: فحص الملكية وإبطال الكاش

public sealed record UpdateCampaignCommand(
    Guid Id, string TitleAr, string TitleEn, string DescriptionAr, string DescriptionEn,
    decimal GoalAmount, DateTime EndDate, Guid CategoryId, byte[] RowVersion) : IRequest<Result<CampaignAdminResponse>>;

public sealed class UpdateCampaignCommandHandler(
    IUnitOfWork unitOfWork,
    ICampaignAuthorizer authorizer,
    ICacheService cache,
    TimeProvider clock) : IRequestHandler<UpdateCampaignCommand, Result<CampaignAdminResponse>>
{
    public async Task<Result<CampaignAdminResponse>> Handle(UpdateCampaignCommand command, CancellationToken ct)
    {
        var campaign = await unitOfWork.Repository<Campaign>().GetByIdAsync(command.Id, ct);

        // الدفاع في العمق: الـ Controller فحص الدور، وهنا نفحص الملكية على المورد نفسه
        if (campaign is null || !await authorizer.CanManageAsync(campaign))
            return CampaignErrors.NotFound;   // 404 في الحالتين — لا نكشف الوجود

        if (campaign.CategoryId != command.CategoryId &&
            !await unitOfWork.Repository<Category>().AnyAsync(c => c.Id == command.CategoryId, ct))
            return CategoryErrors.NotFound;

        // القواعد 2 و 7 و 8 من الكيان نفسه كما في Sprint 2 — لا نتجاهل الـ Result
        var update = campaign.Update(command.TitleAr, command.TitleEn, command.DescriptionAr, command.DescriptionEn,
            command.GoalAmount, command.EndDate, command.CategoryId, clock.GetUtcNow().UtcDateTime);
        if (update.IsFailure)
            return update.Error;

        unitOfWork.SetOriginalRowVersion(campaign, command.RowVersion);   // CMP-10 كما في Sprint 2

        try
        {
            await unitOfWork.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return CampaignErrors.ConcurrencyConflict;   // 409 — الكاتب الثاني
        }

        await cache.InvalidateCampaignAsync(campaign.Id, ct);   // بعد نجاح الحفظ فقط
        return CampaignAdminResponse.From(campaign);            // يحمل RowVersion الجديد
    }
}

