namespace DonationHub.Application.Features.Campaigns.GetMine;

public sealed record GetMyCampaignsQuery(int Page, int PageSize)
    : IRequest<Result<PagedList<ManagerCampaignResponse>>>;

public sealed record ManagerCampaignResponse(
    Guid Id, string TitleAr, string TitleEn, decimal GoalAmount, decimal RaisedAmount,
    DateTime EndDate, CampaignStatus Status, DateTime CreatedAt);

public sealed class GetMyCampaignsQueryHandler(IReadDbContext db, ICurrentUser currentUser)
    : IRequestHandler<GetMyCampaignsQuery, Result<PagedList<ManagerCampaignResponse>>>
{
    public async Task<Result<PagedList<ManagerCampaignResponse>>> Handle(GetMyCampaignsQuery query, CancellationToken ct)
    {
        var ownerId = currentUser.UserId;

        var campaigns = db.Campaigns
            .Where(c => c.CreatedByUserId == ownerId)           // كل الحالات، بلا فلتر Status
            .OrderByDescending(c => c.CreatedAt).ThenBy(c => c.Id)
            .Select(c => new ManagerCampaignResponse(
                c.Id, c.TitleAr, c.TitleEn, c.GoalAmount, c.RaisedAmount, c.EndDate, c.Status, c.CreatedAt));

        return await PagedList<ManagerCampaignResponse>.CreateAsync(campaigns, query.Page, query.PageSize, ct);
    }
}

