namespace DonationHub.Application.Features.Donations.Create;

public sealed record CreateDonationCommand(Guid CampaignId, decimal Amount) : IRequest<Result<DonationResponse>>;

public sealed class CreateDonationCommandValidator : AbstractValidator<CreateDonationCommand>
{
    public CreateDonationCommandValidator(IStringLocalizer<ValidationMessages> localizer)
    {
        RuleFor(x => x.CampaignId).NotEmpty();
        RuleFor(x => x.Amount)
            .GreaterThan(0).WithMessage(_ => localizer["Donation.AmountMustBePositive"])
            .PrecisionScale(18, 2, ignoreTrailingZeros: true).WithMessage(_ => localizer["Donation.AmountPrecision"]);
        // النطاق [Min, Max] قاعدة عمل (422) وليس تحققًا شكليًّا (400) ← يُفحص في الـ handler/Domain
    }
}

public sealed class CreateDonationCommandHandler(
    IUnitOfWork unitOfWork,
    ICurrentUser currentUser,
    IOptions<DonationOptions> options,
    TimeProvider clock) : IRequestHandler<CreateDonationCommand, Result<DonationResponse>>
{
    public async Task<Result<DonationResponse>> Handle(CreateDonationCommand command, CancellationToken ct)
    {
        var campaign = await unitOfWork.Repository<Campaign>().GetByIdAsync(command.CampaignId, ct);
        if (campaign is null)
            return CampaignErrors.NotFound;

        var now = clock.GetUtcNow().UtcDateTime;
        var limits = options.Value;

        // الأخطاء المتوقعة تُرجَع كـ Result (SRS §6.1)؛ والـ Domain يبقى خط الدفاع الأخير
        if (campaign.Status != CampaignStatus.Active || campaign.EndDate <= now)
            return CampaignErrors.NotActive;                  // القاعدة 3 ← 409

        if (command.Amount < limits.MinAmount || command.Amount > limits.MaxAmount)
            return DonationErrors.AmountOutOfRange;           // القاعدة 4 ← 422

        var donation = Donation.Create(campaign, currentUser.UserId, command.Amount,
            limits.MinAmount, limits.MaxAmount, now);

        await unitOfWork.Repository<Donation>().AddAsync(donation, ct);
        await unitOfWork.SaveChangesAsync(ct);

        return DonationResponse.From(donation);
    }
}

