namespace DonationHub.Application.Features.Donations.GetById;

public sealed record GetDonationByIdQuery(Guid Id) : IRequest<Result<DonationDetailsResponse>>;

public sealed class GetDonationByIdQueryHandler(IUnitOfWork unitOfWork, ICurrentUser currentUser)
    : IRequestHandler<GetDonationByIdQuery, Result<DonationDetailsResponse>>
{
    public async Task<Result<DonationDetailsResponse>> Handle(GetDonationByIdQuery query, CancellationToken ct)
    {
        var donation = await unitOfWork.Repository<Donation>().GetByIdAsync(query.Id, ct);

        var canSee = donation is not null
            && (donation.DonorUserId == currentUser.UserId || currentUser.IsInRole(Roles.Admin));
        if (!canSee)
            return DonationErrors.NotFound;                       // 404 — لا نكشف أنه موجود

        var campaign = await unitOfWork.Repository<Campaign>().GetByIdAsync(donation!.CampaignId, ct);
        var title = campaign is null ? "—" : (CurrentLanguage.IsArabic ? campaign.TitleAr : campaign.TitleEn);

        return new DonationDetailsResponse(donation.Id, donation.CampaignId, title, donation.Amount,
            donation.Status, donation.CreatedAt, donation.CompletedAt, donation.ReceiptNumber);
    }
}

