// في Application:  public interface IReceiptNumberGenerator { Task<string> NextAsync(DateTime utcNow, CancellationToken ct); }
// في AppDbContext.OnModelCreating:  builder.HasSequence<long>("ReceiptNumbers", schema: "dbo").StartsAt(1).IncrementsBy(1);
// ثم: dotnet ef migrations add AddReceiptNumberSequence
internal sealed class SqlReceiptNumberGenerator(AppDbContext db) : IReceiptNumberGenerator
{
    public async Task<string> NextAsync(DateTime utcNow, CancellationToken ct)
    {
        // ToListAsync وليس SingleAsync: الأخيرة تلفّ الـ SQL في subquery،
        // و SQL Server يمنع NEXT VALUE FOR داخل الـ derived tables
        var values = await db.Database
            .SqlQuery<long>($"SELECT NEXT VALUE FOR dbo.ReceiptNumbers AS [Value]")
            .ToListAsync(ct);

        return string.Create(CultureInfo.InvariantCulture, $"DN-{utcNow.Year}-{values[0]:D6}");
    }
}

using DonationHub.Application.Abstractions;
using DonationHub.Application.Common.Caching;
