namespace DonationHub.UnitTests.Domain;

public sealed class DonationTests
{
    private static readonly DateTime Now = new(2026, 11, 25, 10, 0, 0, DateTimeKind.Utc);

    private static Campaign NewCampaign(decimal goal = 100m) =>
        Campaign.Create("حملة", "Campaign", "وصف", "Description", goal, Now.AddDays(5),
            Guid.NewGuid(), Guid.NewGuid(), Now).Value;

    private static Donation NewDonation(Campaign campaign, decimal amount) =>
        Donation.Create(campaign, Guid.NewGuid(), amount, 1m, 10_000m, Now);

    [Theory]
    [InlineData(0.99)]
    [InlineData(10_000.01)]
    public void Create_AmountOutsideRange_Throws(double amount)
    {
        var act = () => NewDonation(NewCampaign(), (decimal)amount);

        act.Should().Throw<DomainException>().Which.Code.Should().Be("Donation.AmountOutOfRange");
    }

    [Fact]
    public void Create_CampaignEnded_Throws()
    {
        var campaign = NewCampaign();

        var act = () => Donation.Create(campaign, Guid.NewGuid(), 10m, 1m, 10_000m, Now.AddDays(6));

        act.Should().Throw<DomainException>().Which.Code.Should().Be("Campaign.NotActive");
    }

    [Fact]
    public void MarkSucceeded_GoalReached_CompletesCampaign()
    {
        var campaign = NewCampaign(goal: 100m);
        var donation = NewDonation(campaign, 100m);

        donation.MarkSucceeded(campaign, "DN-2026-000001", Now);

        donation.Status.Should().Be(DonationStatus.Succeeded);
        donation.CompletedAt.Should().Be(Now);
        campaign.RaisedAmount.Should().Be(100m);
        campaign.Status.Should().Be(CampaignStatus.Completed);
    }

    [Fact]
    public void MarkSucceeded_AlreadySucceeded_Throws()
    {
        var campaign = NewCampaign();
        var donation = NewDonation(campaign, 10m);
        donation.MarkSucceeded(campaign, "DN-2026-000001", Now);

        var act = () => donation.MarkSucceeded(campaign, "DN-2026-000002", Now);

        act.Should().Throw<DomainException>().Which.Code.Should().Be("Donation.InvalidState");
    }

    [Fact]
    public void MarkSucceeded_LatePaymentOnCompletedCampaign_IsAcceptedWithoutStatusChange()
    {
        var campaign = NewCampaign(goal: 100m);
        var first = NewDonation(campaign, 100m);
        var late = NewDonation(campaign, 50m);          // أُنشئ والحملة ما زالت نشطة
        first.MarkSucceeded(campaign, "DN-2026-000001", Now);

        late.MarkSucceeded(campaign, "DN-2026-000002", Now.AddMinutes(5));

        late.Status.Should().Be(DonationStatus.Succeeded);
        campaign.RaisedAmount.Should().Be(150m);
        campaign.Status.Should().Be(CampaignStatus.Completed);
    }
}

