public sealed class DonationHandlersTests
{
    private readonly FakeTimeProvider _clock = new(new DateTimeOffset(2026, 11, 25, 10, 0, 0, TimeSpan.Zero));
    private readonly Mock<IUnitOfWork> _unitOfWork = new();
    private readonly Mock<IGenericRepository<Campaign>> _campaigns = new();
    private readonly Mock<IGenericRepository<Donation>> _donations = new();
    private readonly Mock<ICurrentUser> _currentUser = new();
    private readonly Guid _donorId = Guid.NewGuid();

    public DonationHandlersTests()
    {
        _unitOfWork.Setup(u => u.Repository<Campaign>()).Returns(_campaigns.Object);
        _unitOfWork.Setup(u => u.Repository<Donation>()).Returns(_donations.Object);
        _currentUser.Setup(u => u.UserId).Returns(_donorId);
    }

    private DateTime Now => _clock.GetUtcNow().UtcDateTime;

    private Campaign GivenCampaign(decimal goal = 1_000m)
    {
        var campaign = Campaign.Create("حملة", "Campaign", "وصف", "Description", goal, Now.AddDays(10),
            Guid.NewGuid(), Guid.NewGuid(), Now).Value;
        _campaigns.Setup(r => r.GetByIdAsync(campaign.Id, It.IsAny<CancellationToken>())).ReturnsAsync(campaign);
        return campaign;
    }

    private CreateDonationCommandHandler CreateHandler() =>
        new(_unitOfWork.Object, _currentUser.Object, Options.Create(new DonationOptions()), _clock);

    [Fact]
    public async Task Create_ValidRequest_AddsPendingDonation()
    {
        var campaign = GivenCampaign();

        var result = await CreateHandler().Handle(new CreateDonationCommand(campaign.Id, 25m), CancellationToken.None);

        result.IsSuccess.Should().BeTrue();
        result.Value.Status.Should().Be(DonationStatus.Pending);
        _donations.Verify(r => r.AddAsync(
            It.Is<Donation>(d => d.DonorUserId == _donorId && d.Amount == 25m), It.IsAny<CancellationToken>()), Times.Once);
        _unitOfWork.Verify(u => u.SaveChangesAsync(It.IsAny<CancellationToken>()), Times.Once);
    }

    [Theory]
    [InlineData(0.5)]
    [InlineData(10_000.5)]
    public async Task Create_AmountOutOfRange_Returns422Error(double amount)
    {
        var campaign = GivenCampaign();

        var result = await CreateHandler().Handle(new CreateDonationCommand(campaign.Id, (decimal)amount), CancellationToken.None);

        result.Error.Should().Be(DonationErrors.AmountOutOfRange);
        _unitOfWork.Verify(u => u.SaveChangesAsync(It.IsAny<CancellationToken>()), Times.Never);
    }

    [Fact]
    public async Task Create_CampaignEnded_ReturnsNotActive()
    {
        var campaign = GivenCampaign();
        _clock.Advance(TimeSpan.FromDays(11));                      // تجاوزنا EndDate

        var result = await CreateHandler().Handle(new CreateDonationCommand(campaign.Id, 25m), CancellationToken.None);

        result.Error.Should().Be(CampaignErrors.NotActive);
    }

    [Fact]
    public async Task GetById_DonationOfAnotherUser_ReturnsNotFound()
    {
        var campaign = GivenCampaign();
        var donation = Donation.Create(campaign, Guid.NewGuid(), 25m, 1m, 10_000m, Now);   // متبرع آخر
        _donations.Setup(r => r.GetByIdAsync(donation.Id, It.IsAny<CancellationToken>())).ReturnsAsync(donation);

        var handler = new GetDonationByIdQueryHandler(_unitOfWork.Object, _currentUser.Object);
        var result = await handler.Handle(new GetDonationByIdQuery(donation.Id), CancellationToken.None);

        result.Error.Should().Be(DonationErrors.NotFound);         // وليس Forbidden
    }

    [Fact]
    public async Task MarkSucceeded_PendingDonation_RunsWholeSuccessFlow()
    {
        var campaign = GivenCampaign(goal: 100m);
        var donation = Donation.Create(campaign, _donorId, 100m, 1m, 10_000m, Now);
        _donations.Setup(r => r.GetByIdAsync(donation.Id, It.IsAny<CancellationToken>())).ReturnsAsync(donation);
        var receipts = new Mock<IReceiptNumberGenerator>();
        receipts.Setup(r => r.NextAsync(It.IsAny<DateTime>(), It.IsAny<CancellationToken>())).ReturnsAsync("DN-2026-000042");

        var flow = new DonationSuccessFlow(_unitOfWork.Object, receipts.Object, Mock.Of<ICacheService>(),
            _clock, NullLogger<DonationSuccessFlow>.Instance);
        var result = await flow.ExecuteAsync(donation.Id, CancellationToken.None);

        result.IsSuccess.Should().BeTrue();
        donation.Status.Should().Be(DonationStatus.Succeeded);
        donation.ReceiptNumber.Should().Be("DN-2026-000042");
        campaign.RaisedAmount.Should().Be(100m);
        campaign.Status.Should().Be(CampaignStatus.Completed);
    }
}

using Microsoft.EntityFrameworkCore;

namespace DonationHub.Application.Common.Paging;

public static class PagingDefaults
{
    public const int DefaultPageSize = 20;
    public const int MaxPageSize = 50;
}

// الشكل حسب SRS §6.8: { items, page, pageSize, totalCount, totalPages }
public sealed record PagedList<T>(IReadOnlyList<T> Items, int Page, int PageSize, int TotalCount)
{
    public int TotalPages => TotalCount == 0 ? 0 : (int)Math.Ceiling(TotalCount / (double)PageSize);

    public static async Task<PagedList<T>> CreateAsync(
        IQueryable<T> query, int page, int pageSize, CancellationToken ct = default)
    {
        page = Math.Max(page, 1);
        pageSize = Math.Clamp(pageSize, 1, PagingDefaults.MaxPageSize);   // حماية إضافية خلف الـ validator

        var totalCount = await query.CountAsync(ct);                       // SELECT COUNT(*) ...
        var items = await query
            .Skip((page - 1) * pageSize)                                   // OFFSET ... ROWS
            .Take(pageSize)                                                // FETCH NEXT ... ROWS ONLY
            .ToListAsync(ct);

        return new PagedList<T>(items, page, pageSize, totalCount);
    }
}

