namespace DonationHub.Application.Features.Campaigns.List;

public sealed record GetCampaignsQuery : IRequest<Result<PagedList<CampaignSummaryResponse>>>
{
    public int Page { get; init; } = 1;
    public int PageSize { get; init; } = PagingDefaults.DefaultPageSize;
    public string? Search { get; init; }
    public Guid? CategoryId { get; init; }
    public CampaignStatus? Status { get; init; }          // الافتراضي Active (CMP-04)
    public string? SortBy { get; init; }                  // endDate | raisedAmount | createdAt
    public string? SortDirection { get; init; }           // asc | desc
}

// يحل محل GetActiveCampaignsQuery و CampaignSummaryResponse من Sprint 2 (احذفهما): القائمة صارت مقسّمة،
// و progressPercent/daysLeft في التفاصيل فقط (CMP-05). استجابة عامة ← Title واحد بلغة الطلب (CMP-11)
public sealed record CampaignSummaryResponse(
    Guid Id, string Title, decimal GoalAmount, decimal RaisedAmount,
    DateTime EndDate, CampaignStatus Status, Guid CategoryId);

public sealed class GetCampaignsQueryValidator : AbstractValidator<GetCampaignsQuery>
{
    private static readonly string[] SortFields = ["endDate", "raisedAmount", "createdAt"];

    public GetCampaignsQueryValidator()
    {
        RuleFor(x => x.Page).GreaterThanOrEqualTo(1);
        RuleFor(x => x.PageSize).InclusiveBetween(1, PagingDefaults.MaxPageSize);
        RuleFor(x => x.Search).MaximumLength(100);
        RuleFor(x => x.SortBy)
            .Must(s => s is null || SortFields.Contains(s, StringComparer.OrdinalIgnoreCase));
        RuleFor(x => x.SortDirection)
            .Must(d => d is null || d.Equals("asc", StringComparison.OrdinalIgnoreCase)
                                 || d.Equals("desc", StringComparison.OrdinalIgnoreCase));
    }
}

using DonationHub.Application.Abstractions;
using DonationHub.Application.Common.Caching;
using DonationHub.Application.Common.Localization;
