namespace DonationHub.Application.Features.Campaigns.List;

public sealed class GetCampaignsQueryHandler(IReadDbContext db, ICacheService cache, TimeProvider clock)
    : IRequestHandler<GetCampaignsQuery, Result<PagedList<CampaignSummaryResponse>>>
{
    public async Task<Result<PagedList<CampaignSummaryResponse>>> Handle(GetCampaignsQuery q, CancellationToken ct)
    {
        var lang = CurrentLanguage.Code;
        var version = await cache.GetCampaignListVersionAsync(ct);

        // اللغة + كل معاملات الاستعلام داخل المفتاح، وإلا يرى المستخدم العربي صفحة إنجليزية مخزّنة
        var key = CacheKeys.CampaignList(version, lang,
            $"page={q.Page}:size={q.PageSize}:cat={q.CategoryId}:status={q.Status ?? CampaignStatus.Active}" +
            $":search={q.Search?.Trim().ToLowerInvariant()}:sort={q.SortBy?.ToLowerInvariant()}:{q.SortDirection?.ToLowerInvariant()}");

        return await cache.GetOrCreateAsync(key, token => QueryAsync(q, lang == "ar", token),
            CacheProfile.CampaignList, ct);
    }

    private Task<PagedList<CampaignSummaryResponse>> QueryAsync(GetCampaignsQuery q, bool isArabic, CancellationToken ct)
    {
        var status = q.Status ?? CampaignStatus.Active;
        var query = db.Campaigns.Where(c => c.Status == status);

        if (status == CampaignStatus.Active)                       // «نشطة» = Active ولم ينتهِ تاريخها (كما في Sprint 2)
        {
            var now = clock.GetUtcNow().UtcDateTime;
            query = query.Where(c => c.EndDate > now);
        }

        if (q.CategoryId is { } categoryId)
            query = query.Where(c => c.CategoryId == categoryId);

        if (!string.IsNullOrWhiteSpace(q.Search))
        {
            var term = q.Search.Trim();
            query = isArabic                                       // البحث بلغة الطلب الحالية
                ? query.Where(c => c.TitleAr.Contains(term))
                : query.Where(c => c.TitleEn.Contains(term));
        }

        var descending = string.Equals(q.SortDirection, "desc", StringComparison.OrdinalIgnoreCase);

        // قائمة بيضاء: كل قيمة مسموحة مربوطة بـ expression معروف — لا أسماء أعمدة من المستخدم
        var ordered = (q.SortBy?.ToLowerInvariant(), descending) switch
        {
            ("enddate", false) => query.OrderBy(c => c.EndDate),
            ("enddate", true) => query.OrderByDescending(c => c.EndDate),
            ("raisedamount", false) => query.OrderBy(c => c.RaisedAmount),
            ("raisedamount", true) => query.OrderByDescending(c => c.RaisedAmount),
            ("createdat", false) => query.OrderBy(c => c.CreatedAt),
            _ => query.OrderByDescending(c => c.CreatedAt)         // الافتراضي: الأحدث أولًا
        };

        var projected = ordered
            .ThenBy(c => c.Id)                                     // ترتيب ثابت حتى لا تتكرر عناصر بين الصفحات
            .Select(c => new CampaignSummaryResponse(
                c.Id, isArabic ? c.TitleAr : c.TitleEn, c.GoalAmount, c.RaisedAmount,
                c.EndDate, c.Status, c.CategoryId));

        return PagedList<CampaignSummaryResponse>.CreateAsync(projected, q.Page, q.PageSize, ct);
    }
}

