namespace DonationHub.Application.Features.Donations.AdminList;

public sealed record GetAdminDonationsQuery : IRequest<Result<PagedList<AdminDonationResponse>>>
{
    public int Page { get; init; } = 1;
    public int PageSize { get; init; } = PagingDefaults.DefaultPageSize;
    public DonationStatus? Status { get; init; }
    public Guid? CampaignId { get; init; }
    public Guid? DonorId { get; init; }
    public DateTime? From { get; init; }
    public DateTime? To { get; init; }
}

// endpoint إداري ← العنوان باللغتين
public sealed record AdminDonationResponse(
    Guid Id, Guid CampaignId, string CampaignTitleAr, string CampaignTitleEn, Guid DonorUserId,
    decimal Amount, DonationStatus Status, DateTime CreatedAt, string? ReceiptNumber);

public sealed class GetAdminDonationsQueryHandler(IReadDbContext db)
    : IRequestHandler<GetAdminDonationsQuery, Result<PagedList<AdminDonationResponse>>>
{
    public async Task<Result<PagedList<AdminDonationResponse>>> Handle(GetAdminDonationsQuery q, CancellationToken ct)
    {
        var donations = db.Donations;

        if (q.Status is { } status) donations = donations.Where(d => d.Status == status);
        if (q.CampaignId is { } campaignId) donations = donations.Where(d => d.CampaignId == campaignId);
        if (q.DonorId is { } donorId) donations = donations.Where(d => d.DonorUserId == donorId);
        if (q.From is { } from) donations = donations.Where(d => d.CreatedAt >= from);
        if (q.To is { } to) donations = donations.Where(d => d.CreatedAt < to);   // To حصري

        var rows =
            from d in donations
            join c in db.CampaignsIncludingDeleted on d.CampaignId equals c.Id   // نُظهر التبرعات حتى لحملة محذوفة
            orderby d.CreatedAt descending, d.Id
            select new AdminDonationResponse(d.Id, d.CampaignId, c.TitleAr, c.TitleEn, d.DonorUserId,
                d.Amount, d.Status, d.CreatedAt, d.ReceiptNumber);

        return await PagedList<AdminDonationResponse>.CreateAsync(rows, q.Page, q.PageSize, ct);
    }
}

namespace DonationHub.Application.Common.Caching;

public enum CacheProfile { Categories, CampaignList, CampaignDetails, Version }

public interface ICacheService
{
    Task<T?> GetAsync<T>(string key, CancellationToken ct = default);
    Task SetAsync<T>(string key, T value, CacheProfile profile, CancellationToken ct = default);
    Task RemoveAsync(string key, CancellationToken ct = default);
}

public static class CacheKeys
{
    public static readonly string[] Languages = ["en", "ar"];
    public const string CampaignListVersion = "campaigns:list:version";

    public static string CategoriesList(string lang) => $"categories:list:{lang}";
    public static string CampaignDetails(Guid id, string lang) => $"campaigns:details:{id}:{lang}";
    public static string CampaignList(string version, string lang, string queryPart) =>
        $"campaigns:list:v{version}:{lang}:{queryPart}";
}

namespace DonationHub.Application.Common.Caching;

public static class CacheServiceExtensions
{
    // نمط cache-aside: اقرأ من الكاش ← إن لم يوجد اقرأ من DB ← خزّن ← أرجِع
    public static async Task<T> GetOrCreateAsync<T>(this ICacheService cache, string key,
        Func<CancellationToken, Task<T>> factory, CacheProfile profile, CancellationToken ct = default)
    {
        var cached = await cache.GetAsync<T>(key, ct);
        if (cached is not null) return cached;

        var value = await factory(ct);
        if (value is not null)
            await cache.SetAsync(key, value, profile, ct);
        return value;
    }

    public static async Task<string> GetCampaignListVersionAsync(this ICacheService cache, CancellationToken ct = default) =>
        await cache.GetAsync<string>(CacheKeys.CampaignListVersion, ct) ?? "0";

    // تُستدعى عند: إنشاء/تعديل/حذف حملة، تغيّر حالتها (Job الانتهاء في Sprint 4)، ونجاح تبرع
    public static async Task InvalidateCampaignAsync(this ICacheService cache, Guid campaignId, CancellationToken ct = default)
    {
        foreach (var lang in CacheKeys.Languages)
            await cache.RemoveAsync(CacheKeys.CampaignDetails(campaignId, lang), ct);

        await cache.SetAsync(CacheKeys.CampaignListVersion, Guid.NewGuid().ToString("N"), CacheProfile.Version, ct);
    }

    // تُستدعى عند إنشاء/تعديل/حذف تصنيف
    public static async Task InvalidateCategoriesAsync(this ICacheService cache, CancellationToken ct = default)
    {
        foreach (var lang in CacheKeys.Languages)
            await cache.RemoveAsync(CacheKeys.CategoriesList(lang), ct);

        // القوائم قد تُفلتر بالتصنيف ← نبطلها أيضًا
        await cache.SetAsync(CacheKeys.CampaignListVersion, Guid.NewGuid().ToString("N"), CacheProfile.Version, ct);
    }
}

using System.ComponentModel.DataAnnotations;
