namespace DonationHub.Infrastructure.Caching;

public sealed class CacheOptions
{
    public const string SectionName = "Cache";

    [Range(1, 1440)] public int CategoriesMinutes { get; init; } = 60;
    [Range(1, 1440)] public int CampaignListMinutes { get; init; } = 2;
    [Range(1, 1440)] public int CampaignDetailsSlidingMinutes { get; init; } = 5;
    [Range(1, 1440)] public int CampaignDetailsAbsoluteMinutes { get; init; } = 30;
    [Range(1, 10080)] public int VersionKeyMinutes { get; init; } = 1440;
}

internal readonly record struct CacheEntrySettings(TimeSpan? Absolute, TimeSpan? Sliding)
{
    public static CacheEntrySettings For(CacheProfile profile, CacheOptions o) => profile switch
    {
        CacheProfile.Categories => new(TimeSpan.FromMinutes(o.CategoriesMinutes), null),
        CacheProfile.CampaignList => new(TimeSpan.FromMinutes(o.CampaignListMinutes), null),
        CacheProfile.CampaignDetails => new(TimeSpan.FromMinutes(o.CampaignDetailsAbsoluteMinutes),
                                            TimeSpan.FromMinutes(o.CampaignDetailsSlidingMinutes)),
        CacheProfile.Version => new(TimeSpan.FromMinutes(o.VersionKeyMinutes), null),
        _ => throw new ArgumentOutOfRangeException(nameof(profile))
    };
}

using DonationHub.Application.Common.Caching;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Options;

namespace DonationHub.Infrastructure.Caching;

internal sealed class MemoryCacheService(IMemoryCache cache, IOptions<CacheOptions> options) : ICacheService
{
    public Task<T?> GetAsync<T>(string key, CancellationToken ct = default) =>
        Task.FromResult(cache.TryGetValue(key, out T? value) ? value : default);

    public Task SetAsync<T>(string key, T value, CacheProfile profile, CancellationToken ct = default)
    {
        var settings = CacheEntrySettings.For(profile, options.Value);
        cache.Set(key, value, new MemoryCacheEntryOptions
        {
            AbsoluteExpirationRelativeToNow = settings.Absolute,
            SlidingExpiration = settings.Sliding
        });
        return Task.CompletedTask;
    }

    public Task RemoveAsync(string key, CancellationToken ct = default)
    {
        cache.Remove(key);
        return Task.CompletedTask;
    }
}

using System.Text.Json;
using DonationHub.Application.Common.Caching;
using Microsoft.Extensions.Caching.Distributed;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

namespace DonationHub.Infrastructure.Caching;

internal sealed class DistributedCacheService(
    IDistributedCache cache,
    IOptions<CacheOptions> options,
    ILogger<DistributedCacheService> logger) : ICacheService
{
    private static readonly JsonSerializerOptions Json = JsonSerializerOptions.Web;

    public async Task<T?> GetAsync<T>(string key, CancellationToken ct = default)
    {
        try
        {
            var bytes = await cache.GetAsync(key, ct);
            return bytes is null ? default : JsonSerializer.Deserialize<T>(bytes, Json);
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            // Redis متوقف ≠ API متوقف: نعتبره cache miss ونقرأ من قاعدة البيانات
            logger.LogWarning(ex, "Cache read failed for key {CacheKey}", key);
            return default;
        }
    }

    public Task SetAsync<T>(string key, T value, CacheProfile profile, CancellationToken ct = default)
    {
        var settings = CacheEntrySettings.For(profile, options.Value);
        return SafeAsync(key, () => cache.SetAsync(key, JsonSerializer.SerializeToUtf8Bytes(value, Json),
            new DistributedCacheEntryOptions
            {
                AbsoluteExpirationRelativeToNow = settings.Absolute,
                SlidingExpiration = settings.Sliding
            }, ct));
    }

    public Task RemoveAsync(string key, CancellationToken ct = default) => SafeAsync(key, () => cache.RemoveAsync(key, ct));

    // الكتابة والحذف كذلك: فشل Redis بعد commit ناجح لا يحوّل الرد إلى 500؛ المفتاح ينتهي بمدته
    private async Task SafeAsync(string key, Func<Task> action)
    {
        try { await action(); }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            logger.LogWarning(ex, "Cache write failed for key {CacheKey}", key);
        }
    }
}

