// GetCampaignByIdQuery(Guid Id): بلا Language — اللغة من CurrentLanguage بدل ContentLanguage (Sprint 2)
public async Task<Result<CampaignDetailsResponse>> Handle(GetCampaignByIdQuery query, CancellationToken ct)
{
    var lang = CurrentLanguage.Code;
    var isArabic = lang == "ar";

    var snapshot = await cache.GetOrCreateAsync(
        CacheKeys.CampaignDetails(query.Id, lang),
        token => db.Campaigns
            .Where(c => c.Id == query.Id)
            .Select(c => new CampaignSnapshot(c.Id, isArabic ? c.TitleAr : c.TitleEn,
                isArabic ? c.DescriptionAr : c.DescriptionEn, c.GoalAmount, c.RaisedAmount,
                c.EndDate, c.Status, c.CategoryId, c.BannerFileName, c.CreatedAt, c.UpdatedAt, c.RowVersion))
            .FirstOrDefaultAsync(token),
        CacheProfile.CampaignDetails, ct);          // null (غير موجودة) لا يُخزَّن

    if (snapshot is null)
        return CampaignErrors.NotFound;

    var now = clock.GetUtcNow().UtcDateTime;                // CampaignSnapshot = حقول Sprint 2 بلا المشتقة؛ From() جديدة تضيفها
    return CampaignDetailsResponse.From(snapshot,
        CampaignCalculations.ProgressPercent(snapshot.RaisedAmount, snapshot.GoalAmount),
        CampaignCalculations.DaysLeft(snapshot.EndDate, now));
}

using Microsoft.AspNetCore.Localization;

namespace DonationHub.Api.Extensions;

public static class LocalizationExtensions
{
    public static IServiceCollection AddApiLocalization(this IServiceCollection services)
    {
        services.AddLocalization();          // بدون ResourcesPath — انظر التحذير أدناه

        services.Configure<RequestLocalizationOptions>(options =>
        {
            string[] cultures = ["en", "ar"];
            options.SetDefaultCulture("en")                    // الرجوع إلى en
                .AddSupportedCultures(cultures)
                .AddSupportedUICultures(cultures);
            options.ApplyCurrentCultureToResponseHeaders = true;   // يضيف Content-Language للرد
            // نعتمد على Accept-Language فقط (لا query string ولا cookie في API)
            options.RequestCultureProviders = [new AcceptLanguageHeaderRequestCultureProvider()];
        });

        return services;
    }
}

