namespace DonationHub.Api.Controllers;

// نفس الملف من Sprint 2 — ErrorTypeExtensions.ToStatusCode() فوق الكلاس يبقى كما هو
[ApiController]
public abstract class ApiControllerBase : ControllerBase
{
    // جديد في Sprint 3: الـ action يصبح سطرًا واحدًا
    protected IActionResult FromResult(Result result) =>
        result.IsSuccess ? NoContent() : ProblemFrom(result.Error);            // 204

    protected IActionResult FromResult<T>(Result<T> result) =>
        result.IsSuccess ? Ok(result.Value) : ProblemFrom(result.Error);       // 200

    // ما زالت نقطة واحدة تحوّل أي Error إلى RFC 9457 ProblemDetails
    protected IActionResult ProblemFrom(Error error)
    {
        var status = error.Type.ToStatusCode();                                // يشمل 413 لـ PayloadTooLarge

        // جديد في Sprint 3: الكتالوج يبقى إنجليزيًّا، ونترجم عند حدود الـ API بالبحث عن error.Code
        var localizer = HttpContext.RequestServices.GetRequiredService<IStringLocalizer<ErrorMessages>>();
        var localized = localizer[error.Code];
        var title = localized.ResourceNotFound ? error.Message : localized.Value;   // fallback للإنجليزية

        // ProblemDetailsFactory يضيف traceId ويطبّق CustomizeProblemDetails (كما في Sprint 2)
        var problem = ProblemDetailsFactory.CreateProblemDetails(
            HttpContext, statusCode: status, title: title, type: $"https://httpstatuses.io/{status}");

        problem.Extensions["code"] = error.Code;
        if (error is ValidationError validation)
        {
            problem.Extensions["errors"] = validation.Errors.ToDictionary(
                e => JsonNamingPolicy.CamelCase.ConvertName(e.Key),   // GoalAmount → goalAmount
                e => e.Value);
        }

        return new ObjectResult(problem)
        {
            StatusCode = status,
            ContentTypes = { "application/problem+json" }
        };
    }
}

// GetCategoriesQuery من Sprint 2 كما هو؛ الجديد: الكاش، والرد العام بلغة الطلب بدل حقلي Ar/En (CMP-11)
public sealed record CategoryResponse(Guid Id, string Name, string? Description);

public sealed class GetCategoriesQueryHandler(IReadDbContext db, ICacheService cache)
    : IRequestHandler<GetCategoriesQuery, Result<IReadOnlyList<CategoryResponse>>>
{
    public async Task<Result<IReadOnlyList<CategoryResponse>>> Handle(GetCategoriesQuery query, CancellationToken ct)
    {
        var lang = CurrentLanguage.Code;
        var isArabic = lang == "ar";

        var items = await cache.GetOrCreateAsync(
            CacheKeys.CategoriesList(lang),
            token => db.Categories
                .OrderBy(c => isArabic ? c.NameAr : c.NameEn)
                .Select(c => new CategoryResponse(c.Id,
                    isArabic ? c.NameAr : c.NameEn,
                    isArabic ? c.DescriptionAr : c.DescriptionEn))
                .ToListAsync(token),
            CacheProfile.Categories, ct);

        return Result<IReadOnlyList<CategoryResponse>>.Success(items);   // T واجهة ← Success صراحةً
    }
}

using Asp.Versioning;
