public static class VersioningExtensions
{
    public static IServiceCollection AddApiVersioningWithOpenApi(this IServiceCollection services)
    {
        services.AddApiVersioning(options =>
            {
                options.DefaultApiVersion = new ApiVersion(1, 0);
                options.AssumeDefaultVersionWhenUnspecified = true;
                options.ReportApiVersions = true;                     // ترويسة api-supported-versions
                options.ApiVersionReader = new UrlSegmentApiVersionReader();
            })
            .AddMvc()
            .AddApiExplorer(options =>
            {
                options.GroupNameFormat = "'v'VVV";                   // 1.0 ← "v1"
                options.SubstituteApiVersionInUrl = true;             // /api/v{version} ← /api/v1 في المستند
            });

        foreach (var document in ApiDocuments.All)
            services.AddOpenApi(document, options => options.AddDocumentTransformer<BearerSecuritySchemeTransformer>());

        return services;
    }
}

