namespace DonationHub.Api.Options;

public sealed class RateLimitOptions
{
    public const string SectionName = "RateLimit";

    [Range(1, 100_000)] public int GlobalPermitLimit { get; init; } = 100;   // لكل IP
    [Range(1, 10_000)] public int AuthPermitLimit { get; init; } = 10;       // لكل IP
    [Range(1, 10_000)] public int DonationsPermitLimit { get; init; } = 20;  // لكل مستخدم
    [Range(1, 3600)] public int WindowSeconds { get; init; } = 60;
}

using System.Globalization;
using System.Security.Claims;
using System.Threading.RateLimiting;
using DonationHub.Api.Options;
using DonationHub.Application.Resources;
using Microsoft.AspNetCore.RateLimiting;
using Microsoft.Extensions.Localization;
using Microsoft.Extensions.Options;

namespace DonationHub.Api.Extensions;

public static class RateLimitPolicies
{
    public const string Auth = "auth";
    public const string Donations = "donations";
    // "global" يُطبَّق كـ GlobalLimiter على كل الطلبات تلقائيًّا
}

public static class RateLimitingExtensions
{
    public static IServiceCollection AddApiRateLimiting(this IServiceCollection services)
    {
        services.AddOptions<RateLimitOptions>()
            .BindConfiguration(RateLimitOptions.SectionName)
            .ValidateDataAnnotations()
            .ValidateOnStart();

        services.AddRateLimiter(options =>
        {
            options.RejectionStatusCode = StatusCodes.Status429TooManyRequests;

            options.GlobalLimiter = PartitionedRateLimiter.Create<HttpContext, string>(http =>
                FixedWindow(http, $"global:{ClientIp(http)}", o => o.GlobalPermitLimit));

            options.AddPolicy(RateLimitPolicies.Auth, http =>
                FixedWindow(http, $"auth:{ClientIp(http)}", o => o.AuthPermitLimit));

            options.AddPolicy(RateLimitPolicies.Donations, http =>
            {
                var user = http.User.FindFirstValue(ClaimTypes.NameIdentifier) ?? ClientIp(http);
                return FixedWindow(http, $"donations:{user}", o => o.DonationsPermitLimit);
            });

            options.OnRejected = OnRejectedAsync;
        });

        return services;
    }

    private static RateLimitPartition<string> FixedWindow(
        HttpContext http, string partitionKey, Func<RateLimitOptions, int> permitLimit)
    {
        var settings = http.RequestServices.GetRequiredService<IOptions<RateLimitOptions>>().Value;

        return RateLimitPartition.GetFixedWindowLimiter(partitionKey, _ => new FixedWindowRateLimiterOptions
        {
            PermitLimit = permitLimit(settings),
            Window = TimeSpan.FromSeconds(settings.WindowSeconds),
            QueueLimit = 0,                     // ارفض فورًا بدل تعليق الطلبات في طابور
            AutoReplenishment = true
        });
    }

    // خلف reverse proxy فعّل UseForwardedHeaders وإلا سيكون IP كل العملاء هو IP الـ proxy
    private static string ClientIp(HttpContext http) =>
        http.Connection.RemoteIpAddress?.ToString() ?? "unknown";

    private static async ValueTask OnRejectedAsync(OnRejectedContext context, CancellationToken ct)
    {
        var http = context.HttpContext;

        var retryAfter = context.Lease.TryGetMetadata(MetadataName.RetryAfter, out var value)
            ? value
            : TimeSpan.FromSeconds(60);
        http.Response.Headers.RetryAfter =
            ((int)Math.Ceiling(retryAfter.TotalSeconds)).ToString(CultureInfo.InvariantCulture);

        var localizer = http.RequestServices.GetRequiredService<IStringLocalizer<ErrorMessages>>();
        var problems = http.RequestServices.GetRequiredService<IProblemDetailsService>();

        await problems.WriteAsync(new ProblemDetailsContext
        {
            HttpContext = http,
            ProblemDetails =
            {
                Status = StatusCodes.Status429TooManyRequests,
                Type = "https://httpstatuses.io/429",
                Title = localizer["Common.RateLimited"],
                Extensions = { ["code"] = "Common.RateLimited" }      // traceId يضيفه AddProblemDetails
            }
        });
    }
}

using System.ComponentModel.DataAnnotations;

namespace DonationHub.Api.Options;

// تنبيه: يوجد أيضًا Microsoft.AspNetCore.Cors.Infrastructure.CorsOptions — لا تستورد الـ namespace ذاك هنا
public sealed class CorsOptions
{
    public const string SectionName = "Cors";

    [Required, MinLength(1)]
    public string[] AllowedOrigins { get; init; } = [];
}

public static class CorsPolicies
{
    public const string Frontend = "frontend";
}

using DonationHub.Api.Options;
using Microsoft.Extensions.Options;

namespace DonationHub.Api.Extensions;

public static class CorsExtensions
{
    public static IServiceCollection AddApiCors(this IServiceCollection services)
    {
        services.AddOptions<CorsOptions>()
            .BindConfiguration(CorsOptions.SectionName)
            .ValidateDataAnnotations()
            .Validate(o => o.AllowedOrigins.All(IsValidOrigin),
                "Cors:AllowedOrigins must contain absolute http(s) origins without '*' or a trailing slash.")
            .ValidateOnStart();

        services.AddCors();

        // نبني السياسة من CorsOptions المُتحقَّق منها عبر DI بدل قراءة IConfiguration يدويًّا
        services.AddOptions<Microsoft.AspNetCore.Cors.Infrastructure.CorsOptions>()
            .Configure<IOptions<CorsOptions>>((cors, appCors) =>
                cors.AddPolicy(CorsPolicies.Frontend, policy => policy
                    .WithOrigins(appCors.Value.AllowedOrigins)
                    .WithMethods("GET", "POST", "PUT", "PATCH", "DELETE")
                    .WithHeaders("Authorization", "Content-Type", "Accept-Language", "Idempotency-Key")
                    .WithExposedHeaders("Location", "Retry-After", "Content-Language")
                    .SetPreflightMaxAge(TimeSpan.FromMinutes(10))));
                    // لا AllowAnyOrigin، ولا AllowCredentials (نستخدم Bearer وليس cookies)

        return services;
    }

    private static bool IsValidOrigin(string origin) =>
        Uri.TryCreate(origin, UriKind.Absolute, out var uri)
        && uri.Scheme is "http" or "https"
        && !origin.EndsWith('/');
}

