using DonationHub.Api.Infrastructure;
using DonationHub.Api.Options;
using DonationHub.Application;
using DonationHub.Infrastructure;
using DonationHub.Infrastructure.Persistence;
using Scalar.AspNetCore;

var builder = WebApplication.CreateBuilder(args);

builder.Services
    .AddApplicationServices()
    .AddInfrastructureServices(builder.Configuration);

builder.Services.AddControllers()
    .AddJsonOptions(o => o.JsonSerializerOptions.Converters.Add(new JsonStringEnumConverter()));
builder.Services.AddProblemDetails(/* CustomizeProblemDetails (traceId + code افتراضي) كما في Sprint 2 */);
builder.Services.AddExceptionHandler<GlobalExceptionHandler>();     // من Sprint 2

builder.Services
    .AddApiVersioningWithOpenApi()
    .AddApiLocalization()
    .AddApiAuthorization()
    .AddApiRateLimiting()
    .AddApiCors();

var app = builder.Build();

app.UseExceptionHandler();
app.UseStatusCodePages();             // كما في Sprint 2: 401/403/404 بلا جسم ← ProblemDetails
app.UseRequestLocalization();          // أولًا: كل ما بعده يكتب رسائل بلغة الطلب

if (app.Environment.IsDevelopment())
{
    app.MapOpenApi();
    app.MapScalarApiReference(options =>
    {
        foreach (var document in ApiDocuments.All)
            options.AddDocument(document, $"DonationHub API {document}");
    });
}

app.UseCors(CorsPolicies.Frontend);    // قبل المصادقة حتى تمر طلبات الـ preflight
app.UseAuthentication();
app.UseRateLimiter();                  // بعد المصادقة: سياسة donations تحتاج userId
app.UseAuthorization();
app.MapControllers();

await DbSeeder.SeedAsync(app.Services, app.Environment.IsDevelopment());

app.Run();

public sealed class CampaignListSpecification(GetCampaignsQuery q, bool isArabic)
{
    public IQueryable<Campaign> Apply(IQueryable<Campaign> query)
    {
        query = query.Where(c => c.Status == (q.Status ?? CampaignStatus.Active));
        if (q.CategoryId is { } categoryId) query = query.Where(c => c.CategoryId == categoryId);
        if (!string.IsNullOrWhiteSpace(q.Search))
            query = isArabic ? query.Where(c => c.TitleAr.Contains(q.Search)) : query.Where(c => c.TitleEn.Contains(q.Search));
        return query;
    }
}
